-- Foundation only: apply to a staging Supabase project first. No live products seeded.
begin;
create type public.staff_role as enum ('owner','staff');
create type public.payment_state as enum ('unpaid','submitted','verified','rejected');
create type public.fulfillment_state as enum ('unconfirmed','confirmed','preparing','ready_for_pickup','out_for_delivery','completed');
create table public.branches(id uuid primary key default gen_random_uuid(), name text not null, region text not null, cutoff time not null default '14:00', timezone text not null default 'Asia/Manila', pickup_rules jsonb not null default '{}', is_active boolean not null default false);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, role public.staff_role not null, branch_id uuid references public.branches);
create function public.is_owner() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='owner') $$;
create function public.can_access_branch(b uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and (role='owner' or (role='staff' and branch_id=b))) $$;
create table public.service_zones(id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches, city text not null, approved boolean not null default false, unique(branch_id,city));
create table public.delivery_rates(id uuid primary key default gen_random_uuid(), zone_id uuid not null references public.service_zones, product_type text not null check(product_type in ('bouquet','standee')), amount_centavos bigint not null check(amount_centavos>=0), unique(zone_id,product_type));
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique);
create table public.products(id uuid primary key default gen_random_uuid(), sku text not null unique, slug text not null unique, name text not null, description text not null default '', category_id uuid references public.categories, occasion_tags text[] not null default '{}', price_centavos bigint check(price_centavos>=0), product_type text not null check(product_type in ('bouquet','standee')), custom_quote boolean not null default false, featured boolean not null default false, lead_time_hours integer not null default 0 check(lead_time_hours>=0), is_active boolean not null default false, updated_at timestamptz not null default now());
create table public.delivery_inclusions(product_id uuid not null references public.products on delete cascade, zone_id uuid not null references public.service_zones, primary key(product_id,zone_id));
create table public.product_variants(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, name text not null, price_centavos bigint not null check(price_centavos>=0));
create table public.product_images(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products on delete cascade, storage_path text not null, alt text not null, position integer not null default 0);
create table public.add_ons(id uuid primary key default gen_random_uuid(), name text not null, price_centavos bigint not null check(price_centavos>=0), is_active boolean not null default false);
create table public.product_add_ons(product_id uuid references public.products on delete cascade, add_on_id uuid references public.add_ons, primary key(product_id,add_on_id));
create table public.branch_inventory(product_id uuid references public.products on delete cascade, branch_id uuid references public.branches, available boolean not null default false, quantity integer check(quantity>=0), updated_at timestamptz not null default now(), primary key(product_id,branch_id));
create table public.carts(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users, items jsonb not null default '[]', updated_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches, customer_id uuid references auth.users, request_state text not null default 'submitted' check(request_state in ('draft','submitted','needs_review','quote_pending','awaiting_payment','reschedule_requested','cancelled_before_payment','issue_reported')), payment_state public.payment_state not null default 'unpaid', fulfillment_state public.fulfillment_state not null default 'unconfirmed', mode text not null check(mode in ('delivery','pickup')), preferred_date date not null, preferred_window text not null, subtotal_centavos bigint check(subtotal_centavos>=0), fee_centavos bigint check(fee_centavos>=0), total_centavos bigint check(total_centavos>=0), deposit_percent integer not null default 100 check(deposit_percent between 50 and 100), deposit_approved_by uuid references public.profiles, approved_by uuid references public.profiles, approved_at timestamptz, created_at timestamptz not null default now(), check(mode<>'pickup' or fee_centavos=0), check(deposit_percent=100 or deposit_approved_by is not null), check(fulfillment_state='unconfirmed' or approved_by is not null));
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, product_id uuid references public.products, snapshot jsonb not null, quantity integer not null check(quantity between 1 and 20), unit_price_centavos bigint check(unit_price_centavos>=0), card_message text check(length(card_message)<=300));
create table public.order_addresses(order_id uuid primary key references public.orders on delete cascade, customer_name text not null, customer_email text not null, customer_phone text not null, recipient_name text not null, recipient_phone text not null, address text, city text, instructions text, delete_after timestamptz not null default now()+interval '90 days');
create table public.order_status_events(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders on delete cascade, actor_id uuid references auth.users, old_state jsonb, new_state jsonb not null, created_at timestamptz not null default now());
create table public.payment_instructions(id uuid primary key default gen_random_uuid(), method text not null check(method in ('GCash','Maya','GoTyme','MariBank','Cash')), instructions text not null, is_active boolean not null default false);
create table public.payment_records(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders, method text not null check(method in ('GCash','Maya','GoTyme','MariBank','Cash')), amount_centavos bigint not null check(amount_centavos>0), state public.payment_state not null default 'submitted', verified_by uuid references public.profiles, verified_at timestamptz, created_at timestamptz not null default now(), check(state<>'verified' or (verified_by is not null and verified_at is not null)));
create table public.payment_proof_files(id uuid primary key default gen_random_uuid(), payment_record_id uuid not null references public.payment_records, storage_path text not null unique, mime_type text not null check(mime_type in ('image/jpeg','image/png','application/pdf')), byte_size bigint not null check(byte_size between 1 and 5242880), delete_after timestamptz not null default now()+interval '90 days');
create table public.custom_quote_requests(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders, request text not null, quote_centavos bigint check(quote_centavos>=0), approved_by uuid references public.profiles);
create table public.fulfillment_notes(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders, author_id uuid not null references public.profiles, note text not null, created_at timestamptz not null default now());
create table public.holiday_cutoffs(id uuid primary key default gen_random_uuid(), branch_id uuid not null references public.branches, date date not null, cutoff time, closed boolean not null default false, peak_season boolean not null default false, unique(branch_id,date));
create table public.site_settings(key text primary key, value jsonb not null, updated_at timestamptz not null default now());
-- Deny access by default on every table, including future auxiliary tables in this migration.
do $$ declare t text; begin foreach t in array array['branches','profiles','service_zones','delivery_rates','categories','products','delivery_inclusions','product_variants','product_images','add_ons','product_add_ons','branch_inventory','carts','orders','order_items','order_addresses','order_status_events','payment_instructions','payment_records','payment_proof_files','custom_quote_requests','fulfillment_notes','holiday_cutoffs','site_settings'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy owner_access on public.%I for all to authenticated using (public.is_owner()) with check (public.is_owner())',t); end loop; end $$;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy published_products on public.products for select to anon,authenticated using(is_active);
create policy active_branches on public.branches for select to anon,authenticated using(is_active);
create policy approved_zones on public.service_zones for select to anon,authenticated using(approved and exists(select 1 from public.branches b where b.id=branch_id and b.is_active));
create policy public_categories on public.categories for select to anon,authenticated using(true);
create policy public_images on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.is_active));
create policy public_variants on public.product_variants for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and p.is_active));
create policy branch_inventory_read on public.branch_inventory for select to authenticated using(public.can_access_branch(branch_id));
create policy branch_order_read on public.orders for select to authenticated using(public.can_access_branch(branch_id));
-- Staff get only their branch's necessary operational records; no anonymous customer/PII reads.
do $$ declare t text; begin foreach t in array array['order_items','order_addresses','order_status_events','payment_records','custom_quote_requests','fulfillment_notes'] loop execute format('create policy branch_read on public.%I for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and public.can_access_branch(o.branch_id)))',t); end loop; end $$;
-- All operational writes remain owner-only until audited role-specific RPCs are implemented.
create function public.audit_order_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.order_status_events(order_id,actor_id,old_state,new_state) values(new.id,auth.uid(),case when tg_op='UPDATE' then jsonb_build_object('request',old.request_state,'payment',old.payment_state,'fulfillment',old.fulfillment_state) else null end,jsonb_build_object('request',new.request_state,'payment',new.payment_state,'fulfillment',new.fulfillment_state)); return new; end $$;
create trigger audit_order after insert or update on public.orders for each row execute function public.audit_order_change();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-proofs','payment-proofs',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
create policy owner_private_proofs on storage.objects for all to authenticated using(bucket_id='payment-proofs' and public.is_owner()) with check(bucket_id='payment-proofs' and public.is_owner());
-- No anonymous proof uploads, no public proof URLs, no automatic payment verification.
commit;
